using UnityEngine; using UnityEditor; using UnityEditor.SceneManagement; using System.IO; using InhaExpress.Client.Presentation;
[System.Serializable] public class HomePoseRecord { public string vehicleId; public Vector3 position; public Quaternion rotation; }
internal class CommandScript : IRunCommand { public void Execute(ExecutionResult result) {
if(EditorApplication.isPlayingOrWillChangePlaymode) {result.Log("STILL_PLAYING");return;}
if(!EditorSceneManager.SaveCurrentModifiedScenesIfUserWantsTo()){result.Log("CANCELLED");return;}
var scene=EditorSceneManager.OpenScene("Assets/CampusSim/Scenes/CampusTerrain.unity");
var pose=JsonUtility.FromJson<HomePoseRecord>(File.ReadAllText("artifacts/high_speed_drive/v01-home-pose.json"));
if(pose.vehicleId!="V01" || Vector2.Distance(new Vector2(pose.position.x,pose.position.z),new Vector2(-40.807f,-321.44579f))>3)throw new System.Exception("Home pose outside configured main gate");
int count=0;foreach(var v in Object.FindObjectsByType<VehicleController>(FindObjectsSortMode.None)) { if(v.OperatorVehicleId!=pose.vehicleId)continue; Undo.RecordObject(v.transform,"Place vehicle at configured home");v.transform.SetPositionAndRotation(pose.position,pose.rotation);PrefabUtility.RecordPrefabInstancePropertyModifications(v.transform);count++;result.Log(v.OperatorVehicleId+" home="+v.transform.position);}
if(count!=1)throw new System.Exception("Unexpected matching vehicle count "+count);
EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);result.Log("HOME_SCENE_SAVED");
} }
